private static Type[] findActualTypeArguments(Class<?> clazz, Class<?> targetRaw) {
    if (clazz == null || clazz.equals(Object.class)) return null;
    // Check interfaces
    for (Type itype : clazz.getGenericInterfaces()) {
        if (itype instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) itype;
            Class<?> raw = (Class<?>) pt.getRawType();
            if (raw.equals(targetRaw)) {
                return pt.getActualTypeArguments();
            }
        } else if (itype instanceof Class) {
            Class<?> itf = (Class<?>) itype;
            if (targetRaw.equals(itf)) {
                // interface raw type, but generic info missing
                return null;
            }
        }
    }
    // Check superclass
    Type superT = clazz.getGenericSuperclass();
    if (superT != null) {
        if (superT instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) superT;
            Class<?> raw = (Class<?>) pt.getRawType();
            if (raw.equals(targetRaw)) {
                return pt.getActualTypeArguments();
            }
        } else if (superT instanceof Class) {
            Class<?> superC = (Class<?>) superT;
            if (targetRaw.equals(superC)) {
                // raw type, but generic info missing
                return null;
            }
        }
        // recursively search up by using the underlying raw type
        Class<?> superRaw = null;
        if (superT instanceof ParameterizedType) {
            superRaw = (Class<?>) ((ParameterizedType) superT).getRawType();
        } else if (superT instanceof Class) {
            superRaw = (Class<?>) superT;
        }
        if (superRaw != null) {
            Type[] args = findActualTypeArguments(superRaw, targetRaw);
            if (args != null) return args;
        }
    }
    // No match in this class or its hierarchy
    return null;
}

