public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "Index: " + index + ", Length: " + len + ", String length: " + str.length());
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Surrogate pair representing a code point > 0xFFFF
            size += 4;
            i++; // Skip the low surrogate
        } else if (Character.isLowSurrogate(ch)) {
            // Unmatched low surrogate, treat as 3 bytes (invalid but for size estimation)
            size += 3;
        } else {
            // BMP non-ASCII character
            size += 3;
        }
    }
    return size;
}

